// Exact factors to liter. Factors per NIST definitions.
var TABLE=[["milliliter","mL",0.001], ["liter","L",1.0], ["kiloliter","kL",1000.0], ["cubic centimeter","cm3",0.001], ["cubic meter","m3",1000.0], ["teaspoon US","tsp",0.00492892159375], ["tablespoon US","tbsp",0.01478676478125], ["fluid ounce US","fl oz",0.0295735295625], ["cup US","cup",0.2365882365], ["pint US","pt",0.473176473], ["quart US","qt",0.946352946], ["gallon US","gal",3.785411784], ["oil barrel","bbl",158.987294928], ["hogshead","hhd",238.480942], ["bushel US","bu",35.23907016688], ["peck US","pk",8.80976754172], ["teaspoon UK","tsp",0.005919388], ["tablespoon UK","tbsp",0.0177582], ["fluid ounce UK","fl oz",0.0284130625], ["pint UK","pt",0.56826125], ["quart UK","qt",1.1365225], ["gallon UK","gal",4.54609], ["UK barrel","bbl",163.65924], ["bushel UK","bu",36.36872], ["cubic inch","in3",0.016387064], ["cubic foot","ft3",28.316846592], ["cubic yard","yd3",764.554857984], ["cord","cord",3624.556], ["acre-foot","ac-ft",1233481.84], ["drop","drop",5e-05], ["dash","dash",0.00092]];
function toBase(v,name){name=String(name).toLowerCase();for(var i=0;i<TABLE.length;i++){if(TABLE[i][0].toLowerCase()===name||TABLE[i][1].toLowerCase()===name)return v*TABLE[i][2];}throw new Error("unknown unit: "+name);}
function convert(v,from,to){var b=toBase(v,from);to=String(to).toLowerCase();for(var i=0;i<TABLE.length;i++){if(TABLE[i][0].toLowerCase()===to||TABLE[i][1].toLowerCase()===to)return b/TABLE[i][2];}throw new Error("unknown unit: "+to);}
